public static partial class UiTests {
 static void ClubUpdateScreens(GameForm f,string evidence){Franchise club=Franchise.Create(new Profile(),new Roster());club.UserTeam=1;club.Credits=60;Set(f,"franchise",club);Set(f,"screen","club");Set(f,"selection",0);f.SavePreview(Path.Combine(evidence,"office.png"));Check(((List<string>)typeof(GameForm).GetMethod("FrontRows",flags).Invoke(f,null)).Contains("MONEY + STADIUM"),"team section exposes stadium money department");Set(f,"selection",3);Call(f,"ActivateSelection");Check((string)Get(f,"screen")=="stadium","office opens stadium and money controls");int price=club.Business.FoodPrice;Set(f,"selection",1);Tap(f,Keys.Enter);Check(club.Business.FoodPrice==price+1,"food price increases through real menu input");Set(f,"selection",0);Tap(f,Keys.Enter);Check(club.Business.FoodPrice==price,"food price decreases through real menu input");Set(f,"selection",3);Tap(f,Keys.Enter);Check(club.Business.ParkingPrice==14,"parking price changes independently");f.SavePreview(Path.Combine(evidence,"stadium-money.png"));
  Set(f,"screen","freeagents");Set(f,"selection",0);f.SavePreview(Path.Combine(evidence,"freeagents.png"));List<string> rows=(List<string>)typeof(GameForm).GetMethod("FrontRows",flags).Invoke(f,null);Check(rows[0].Contains("$")&&!rows[0].Contains(" CR"),"player prices display dollars");Call(f,"ActivateSelection");List<ClubPlayer> people=(List<ClubPlayer>)Get(f,"confirmPlayers");Check(people.Count==1&&people[0].Team==-1,"signing confirmation carries exact player profile");f.SavePreview(Path.Combine(evidence,"sign-player-profile.png"));Set(f,"screen","roster");Set(f,"selection",0);f.SavePreview(Path.Combine(evidence,"roster.png"));rows=(List<string>)typeof(GameForm).GetMethod("FrontRows",flags).Invoke(f,null);people=(List<ClubPlayer>)typeof(GameForm).GetMethod("FrontRowPeople",flags).Invoke(f,new object[]{0,rows});Check(people.Count==1&&people[0].Id==club.Starter(club.UserTeam,0).Id,"named roster row has matching player portrait");
  Call(f,"StartGame");Simulation s=(Simulation)Get(f,"game");Tap(f,Keys.R);Check(s.OnsideRulesPending&&!s.OnsideAttempt,"RB or R opens first-game onside explanation");f.SavePreview(Path.Combine(evidence,"onside-rules.png"));float clock=s.Clock;Step(f,Keys.None,false,5);Check(s.Clock==clock,"explanation pauses gameplay clock");Tap(f,Keys.Enter);Check(s.OnsideAttempt&&s.Spot==30&&s.FirstDown==43&&s.Down==4&&s.State==Phase.PreSnap,"confirm starts real fourth-and-thirteen play");f.SavePreview(Path.Combine(evidence,"onside-try.png"));Tap(f,Keys.Space);typeof(Simulation).GetMethod("EndPlay",flags).Invoke(s,new object[]{43f,"OUT: 13 YDS",false});Tap(f,Keys.Enter);Tap(f,Keys.R);Check(s.OnsideAttempt&&!s.OnsideRulesPending&&s.OnsideAttempts==2,"later attempt skips popup in same game");
  s.NewGame();typeof(Simulation).GetMethod("AfterUserScore",flags).Invoke(s,new object[]{"FIELD GOAL GOOD"});f.SavePreview(Path.Combine(evidence,"kickoff-choice.png"));Tap(f,Keys.X);Check(s.OnsideRulesPending,"score kickoff menu offers onside alternative");Tap(f,Keys.Escape);Tap(f,Keys.Enter);Check(s.State==Phase.Opponent,"normal kickoff remains available after closing rule popup");
  club.FinishGame(club.UserGame.Id,28,7);Set(f,"screen","leaders");Set(f,"selection",0);f.SavePreview(Path.Combine(evidence,"mvp-race.png"));Tap(f,Keys.Right);Check((int)Get(f,"raceCategory")==1,"right moves from MVP race to offensive player of year");f.SavePreview(Path.Combine(evidence,"opot y-race.png".Replace(" ","")));Tap(f,Keys.Right);Check((int)Get(f,"raceCategory")==2,"passing category is available with separate stats");f.SavePreview(Path.Combine(evidence,"passing-leaders.png"));
  club.Fired=true;club.DismissalReason="Results and board confidence fell too far.";Set(f,"screen","franchisehub");Set(f,"selection",0);f.SavePreview(Path.Combine(evidence,"coach-fired.png"));Call(f,"ActivateSelection");Check((string)Get(f,"screen")=="league","fired coach is directed to coaching jobs");f.SavePreview(Path.Combine(evidence,"coaching-jobs.png"));
  Simulation collision=LinePlayTests.TruckScene(1);typeof(Simulation).GetMethod("TruckImpact",flags).Invoke(collision,new object[]{collision.Players[1],true});for(int i=0;i<10;i++)collision.Update(.02f,0,1);Set(f,"game",collision);Set(f,"screen","game");Set(f,"cameraZ",20f);f.SavePreview(Path.Combine(evidence,"spectacular-hit.png"));Check(collision.Players[1].ImpactLevel==2&&collision.Players[1].KnockTime>0,"spectacular launch and turf burst render");Set(f,"matchFixture",-1);Set(f,"screen","home");}
}
